WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_88b1c15ac7012d33>
    <urn:graphragprov:unit:u_fd59db973fa188bd>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
